const express = require('express');
const cors = require('cors');
const { nanoid } = require('nanoid');
const bcrypt = require('bcrypt'); // Добавили bcrypt
const swaggerJsdoc = require('swagger-jsdoc');
const swaggerUi = require('swagger-ui-express');

const app = express();
const port = 3000;

app.use(cors());
app.use(express.json());

// --- Настройка Swagger ---
const swaggerOptions = {
    definition: {
        openapi: '3.0.0',
        info: { title: 'Nail Store API + Auth', version: '1.0.0' },
        servers: [{ url: `http://localhost:${port}` }],
    },
    apis: ['./app.js'],
};
const swaggerSpec = swaggerJsdoc(swaggerOptions);
app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerSpec));

// --- Данные в памяти ---
let users = [];
let products = [
    { id: "1", title: "UV/LED Лампа 48W", category: "Оборудование", description: "Мощная гибридная лампа", price: 2500 },
    { id: "2", title: "Аппарат Strong 210", category: "Оборудование", description: "35000 об/мин", price: 12500 }
];

// --- Функции для работы с паролями ---
async function hashPassword(password) {
    const rounds = 10;
    return await bcrypt.hash(password, rounds);
}

async function verifyPassword(password, hash) {
    return await bcrypt.compare(password, hash);
}

// --- МАРШРУТЫ АУТЕНТИФИКАЦИИ (Практика 7) ---

// Регистрация
app.post('/api/auth/register', async (req, res) => {
    const { email, first_name, last_name, password } = req.body;

    if (!email || !password || !first_name || !last_name) {
        return res.status(400).json({ error: "Все поля обязательны" });
    }

    const existingUser = users.find(u => u.email === email);
    if (existingUser) {
        return res.status(400).json({ error: "Пользователь с таким email уже существует" });
    }

    const hashedPassword = await hashPassword(password);
    
    const newUser = {
        id: nanoid(),
        email,
        first_name,
        last_name,
        password: hashedPassword
    };

    users.push(newUser);
    // Не отправляем пароль обратно в ответе!
    const { password: _, ...userWithoutPass } = newUser;
    res.status(201).json(userWithoutPass);
});

// Вход
app.post('/api/auth/login', async (req, res) => {
    const { email, password } = req.body;

    const user = users.find(u => u.email === email);
    if (!user) {
        return res.status(404).json({ error: "Пользователь не найден" });
    }

    const isMatch = await verifyPassword(password, user.password);
    if (!isMatch) {
        return res.status(401).json({ error: "Неверный пароль" });
    }

    res.json({ success: true, message: "Вход выполнен успешно", user: { email: user.email, first_name: user.first_name } });
});

// --- МАРШРУТЫ ТОВАРОВ (Практика 8-10) ---

app.get('/api/products', (req, res) => res.json(products));

app.get('/api/products/:id', (req, res) => {
    const product = products.find(p => p.id === req.params.id);
    product ? res.json(product) : res.status(404).send();
});

app.post('/api/products', (req, res) => {
    const newProduct = { id: nanoid(6), ...req.body };
    products.push(newProduct);
    res.status(201).json(newProduct);
});

app.patch('/api/products/:id', (req, res) => {
    const index = products.findIndex(p => p.id === req.params.id);
    if (index !== -1) {
        products[index] = { ...products[index], ...req.body };
        res.json(products[index]);
    } else res.status(404).send();
});

app.delete('/api/products/:id', (req, res) => {
    products = products.filter(p => p.id !== req.params.id);
    res.status(204).send();
});

app.listen(port, () => console.log(`Сервер запущен: http://localhost:${port}`));
